import numpy as np,mujoco
s=Session('bookshelf_simple',instance='/app/instance.npz');s.reset();m=s.low.model;d=s.low.data
qstand=d.qpos.copy()
for n,v in [('left_hip_pitch',.2),('right_hip_pitch',.2),('left_knee',.2),('right_knee',.2),('left_ankle',-.6),('right_ankle',-.6)]:qstand[m.jnt_qposadr[m.joint(n).id]]=v

def action(q):
 a=np.empty(m.nu)
 for i in range(m.nu):
  lo,hi=m.actuator_ctrlrange[i]
  if m.actuator_trntype[i]==0:
   ji=int(m.actuator_trnid[i,0]);v=q[m.jnt_qposadr[ji]]
  else:v=0
  a[i]=2*(v-lo)/(hi-lo)-1
 return np.clip(a,-1,1)
for _ in range(130):s.step(action(qstand))
armnames=['left_shoulder_pitch','left_shoulder_roll','left_shoulder_yaw','left_elbow','left_wrist_yaw'];jids=np.array([m.joint(n).id for n in armnames]);dofs=m.jnt_dofadr[jids];adrs=m.jnt_qposadr[jids];body=m.body('lh_palm').id
